// #1432: what the blind suite leaves out of the size ratchet's scope. A file new over 1,500 lines fails, with or
// without a ceiling added for it, a ceiling never rises above the merge base's, and a generated file is out of scope.
import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { copyFileSync, mkdirSync, mkdtempSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';

const script = fileURLToPath(new URL('../scripts/size-ratchet.mjs', import.meta.url));
const OLD = 'src/old.rs';
const NEW = 'src/new.rs';
const rust = (count) => Array.from({ length: count }, (_, i) => `pub const C${i}: u32 = ${i};\n`).join('');

function repo(t) {
  const cwd = realpathSync(mkdtempSync(join(tmpdir(), 'size-ratchet-')));
  t.after(() => rmSync(cwd, { recursive: true, force: true }));
  const git = (...args) => execFileSync('git', ['-c', 'user.name=Fixture', '-c', 'user.email=fixture@example.invalid', '-c', 'commit.gpgsign=false', ...args], { cwd, stdio: 'ignore' });
  const write = (files) => {
    for (const [path, content] of Object.entries(files)) {
      mkdirSync(dirname(join(cwd, path)), { recursive: true });
      writeFileSync(join(cwd, path), typeof content === 'string' ? content : `${JSON.stringify(content)}\n`);
    }
  };
  git('init', '-q');
  mkdirSync(join(cwd, 'scripts'));
  copyFileSync(script, join(cwd, 'scripts', 'size-ratchet.mjs'));
  write({ [OLD]: rust(1600), 'scripts/size-ceilings.json': { [OLD]: 1600 } });
  git('add', '-A');
  git('commit', '-q', '-m', 'base');
  git('update-ref', 'refs/remotes/origin/main', 'HEAD');
  const run = (files) => {
    write(files);
    const result = spawnSync(process.execPath, ['scripts/size-ratchet.mjs'], { cwd, encoding: 'utf8' });
    return { status: result.status, out: result.stdout };
  };
  return run;
}

test('a file new over 1,500 lines fails, with no ceiling or with one the merge base lacks', (t) => {
  const run = repo(t);
  assert.equal(run({}).status, 0);
  let result = run({ [NEW]: rust(1501) });
  assert.equal(result.status, 1, result.out);
  assert.match(result.out, /^FAIL size: src\/new\.rs: 1501 lines, over 1500 with no ceiling$/m);
  result = run({ 'scripts/size-ceilings.json': { [OLD]: 1600, [NEW]: 1501 } });
  assert.equal(result.status, 1, result.out);
  assert.match(result.out, /^FAIL size: src\/new\.rs: 1501 lines, its ceiling of 1501 above the merge base's 1500$/m);
});

test("a ceiling raised above the merge base's fails, and a generated file is out of scope", (t) => {
  const run = repo(t);
  const result = run({ [OLD]: rust(1601), 'scripts/size-ceilings.json': { [OLD]: 1601 } });
  assert.equal(result.status, 1, result.out);
  assert.match(result.out, /^FAIL size: src\/old\.rs: 1601 lines, its ceiling of 1601 above the merge base's 1600$/m);
  const generated = run({ [OLD]: rust(1600), 'scripts/size-ceilings.json': { [OLD]: 1600 }, [NEW]: `// @generated by a tool\n${rust(2000)}` });
  assert.equal(generated.status, 0, generated.out);
});
